PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT DISTINCT ?an WHERE {
  { SELECT ?ag (SUM(?a1) AS ?total) WHERE {
      ?c1 a :Contract ; :agency ?ag ; :amount ?a1 .
    } GROUP BY ?ag }
  { SELECT ?ag ?g (SUM(?a2) AS ?gtotal) WHERE {
      ?c2 a :Contract ; :agency ?ag ; :amount ?a2 ; :supplier ?s .
      ?s :group ?g .
    } GROUP BY ?ag ?g }
  ?ag :name ?an .
  FILTER(?gtotal * 3 > ?total)
}
